    log("pacht→check: Schritt-Überschrift:", kopf?.trim(), "| ha-Feld:", ha, "| Speicher:", st);
    await page.locator("#check").screenshot({ path: `${out}/pacht-check.png` }).catch(() => {});
    log("pacht: Fehler", fehler.length, fehler.slice(0, 2));
